SELECT '1. 5 支函式存在、SECURITY DEFINER、指紋與正式庫相同' AS item, (SELECT count(*) FROM pg_proc p WHERE p.prosecdef AND ((p.oid = to_regprocedure('public.claim_hotelnabe_ari_push_batch(integer)') AND md5(replace(p.prosrc, E'\r', '')) = '57f53b0ba67d5f99f17a45640c11436d') OR (p.oid = to_regprocedure('public.gbp_vault_get(text)') AND md5(replace(p.prosrc, E'\r', '')) = 'c1faaca8da4aac41a2f9792be509c8bf') OR (p.oid = to_regprocedure('public.gbp_vault_set(text, text)') AND md5(replace(p.prosrc, E'\r', '')) = 'f574dbcf36712fb298fe180fc984d792') OR (p.oid = to_regprocedure('public.get_ai_ops_metrics(uuid, integer)') AND md5(replace(p.prosrc, E'\r', '')) = '670f67a22d8e7140fbb14365625acb51') OR (p.oid = to_regprocedure('public.get_rpc_contract(text[])') AND md5(replace(p.prosrc, E'\r', '')) = '442016e1eba30d3bcbb21d3608f4a3e4'))) = 5 AS ok
UNION ALL SELECT '2. 沒有 SECURITY INVOKER 函式呼叫前 4 支', NOT EXISTS (SELECT 1 FROM pg_proc p CROSS JOIN unnest(ARRAY['gbp_vault_get', 'gbp_vault_set', 'get_rpc_contract', 'claim_hotelnabe_ari_push_batch']) AS n(nm) WHERE NOT p.prosecdef AND p.proname <> n.nm AND p.prosrc ~ ('\m' || n.nm || '\M'))
UNION ALL SELECT '3. 沒有任何其他函式（含 DEFINER）呼叫前 4 支', NOT EXISTS (SELECT 1 FROM pg_proc p CROSS JOIN unnest(ARRAY['gbp_vault_get', 'gbp_vault_set', 'get_rpc_contract', 'claim_hotelnabe_ari_push_batch']) AS n(nm) WHERE p.proname <> n.nm AND p.prosrc ~ ('\m' || n.nm || '\M'))
UNION ALL SELECT '4. 沒有 RLS policy 引用這 5 支', NOT EXISTS (SELECT 1 FROM pg_policy pol WHERE COALESCE(pg_get_expr(pol.polqual, pol.polrelid), '') || ' ' || COALESCE(pg_get_expr(pol.polwithcheck, pol.polrelid), '') ~ '(gbp_vault_get|gbp_vault_set|get_rpc_contract|claim_hotelnabe_ari_push_batch|get_ai_ops_metrics)')
UNION ALL SELECT '5. 5 支授權清單皆無 PUBLIC', NOT EXISTS (SELECT 1 FROM pg_proc p, aclexplode(COALESCE(p.proacl, acldefault('f', p.proowner))) a WHERE p.oid IN (to_regprocedure('public.claim_hotelnabe_ari_push_batch(integer)'), to_regprocedure('public.gbp_vault_get(text)'), to_regprocedure('public.gbp_vault_set(text, text)'), to_regprocedure('public.get_ai_ops_metrics(uuid, integer)'), to_regprocedure('public.get_rpc_contract(text[])')) AND a.grantee = 0);

SELECT p.oid::regprocedure::text AS func, p.prosecdef AS secdef, COALESCE(p.proacl::text, 'NULL') AS proacl, md5(replace(p.prosrc, E'\r', '')) AS fp, has_function_privilege('anon', p.oid, 'EXECUTE') AS anon_exec, has_function_privilege('authenticated', p.oid, 'EXECUTE') AS auth_exec, has_function_privilege('service_role', p.oid, 'EXECUTE') AS service_exec
FROM pg_proc p
WHERE p.oid IN (to_regprocedure('public.claim_hotelnabe_ari_push_batch(integer)'), to_regprocedure('public.gbp_vault_get(text)'), to_regprocedure('public.gbp_vault_set(text, text)'), to_regprocedure('public.get_ai_ops_metrics(uuid, integer)'), to_regprocedure('public.get_rpc_contract(text[])'))
ORDER BY 1;
